!flag{draft}{off}
!flag{handout}{on}
!flag{internal}{off}

@frame{Results}::
    !when[or]{draft}{internal} >> \marginpar{re-measure before the talk}
    @itemize::
        \item Throughput doubled
        \item Latency unchanged
    !unless[or]{handout}{internal}::
        \pause
        @{\small} >> \textit{Ask about the tail latency here.}

