            \headuline{CA}{受信信号の周波数領域表現}
            @align*::
                \mathmat{y} = \UnderlineC{$\mathmat{H} \mathmat{D} \mathmat{P}_{\pi} \mathmat{W}$} \mathmat{x} + \mathmat{w} = \UnderlineC{$\mathmat{A}$} \mathmat{x} + \mathmat{w}

