% texflux: examples/content.tfx:155
\begin{itemize}
% texflux: examples/content.tfx:156
\item チャネル応答推定後に特異値分解$\mathcal{O}(N^3)$が必要
% texflux: examples/content.tfx:157
\item EP法の反復1回に$\mathcal{O}(N^2)$の計算コスト\\
% texflux: examples/content.tfx:158
（比較：OFDMは$\mathcal{O}(N\log N)$で復調可能）
\end{itemize}

% texflux: examples/content.tfx:160
\vspace{1em}
% texflux: examples/content.tfx:160
\begin{infobox}{本研究での解決策}
% texflux: examples/content.tfx:161
以下の計算が低コスト$\mathcal{O}(N\log N)$で実行可能な\\\TextCA{新しいSEFDMの変調行列$\mathmat{W}$の設計}
% texflux: examples/content.tfx:162
\begin{itemize}
% texflux: examples/content.tfx:163
\item 行列ベクトル積$\mathmat{W} \mathmat{x}$
% texflux: examples/content.tfx:164
\item 線形MMSEフィルタ$\mathmat{W}^{H} \brkts{ \sigma^2 \mathmat{I} + v \mathmat{W} \mathmat{W}^{H} }^{-1}$
\end{itemize}
\end{infobox}
}
\end{frame}


