                &\BackgroundB{$\UnderlineAcap{$\mathmat{W}$}{DFT} \mathmat{U} \sqrt{\mathmat{\Sigma}}$} \sqrt{\mathmat{\Sigma}} \mathmat{V}^{H}\\

            !before{\vspace{-1em}} >> @infobox{} >> @itemize::
