            @itemize::
                \item 行列ベクトル積$\mathmat{W} \mathmat{x}$
                \item 線形MMSEフィルタ$\mathmat{W}^{H} \brkts{ \sigma^2 \mathmat{I} + v \mathmat{W} \mathmat{W}^{H} }^{-1}$


