                &\mathmat{W}_{\alpha} = \mathmat{U} \BackgroundB{$\displaystyle \mathmat{\Sigma}$} \mathmat{V}^{H} \\
                &\BackgroundB{$\displaystyle \mathmat{\Sigma}$} = \mathrm{diag}\BRKTS{ \sigma_0, \sigma_1, \cdots, \sigma_{N-1}}\\
